const allRows = $input.all().map(i => ({ ...i.json }));

const monthMap = {
  jan:1, january:1, feb:2, february:2, mar:3, march:3,
  apr:4, april:4, may:5, jun:6, june:6, jul:7, july:7,
  aug:8, august:8, sep:9, sept:9, september:9,
  oct:10, october:10, nov:11, november:11, dec:12, december:12,
};

function parseDate(str) {
  if (!str) return null;
  str = str.trim();
  if (/^x+$/i.test(str) || str.startsWith('+')) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) return str;
  const textMatch = str.match(/^(\d{1,2})\s*[-\/]?\s*([a-zA-Z]+)\.?\s*[-\/]?\s*(\d{2,4})/);
  if (textMatch) {
    const day = parseInt(textMatch[1]);
    const month = monthMap[textMatch[2].toLowerCase()];
    let year = parseInt(textMatch[3].substring(0, 4));
    if (year < 100) year += 1900;
    if (month && day >= 1 && day <= 31 && year >= 1900)
      return year + '-' + String(month).padStart(2,'0') + '-' + String(day).padStart(2,'0');
  }
  const numMatch = str.match(/^(\d{1,2})\s*[-\/\.]\s*(\d{1,2})\s*[-\/\.]\s*(\d{4})/);
  if (numMatch) {
    const day = parseInt(numMatch[1]), month = parseInt(numMatch[2]), year = parseInt(numMatch[3]);
    if (month >= 1 && month <= 12 && day >= 1 && day <= 31)
      return year + '-' + String(month).padStart(2,'0') + '-' + String(day).padStart(2,'0');
  }
  const spaceMatch = str.match(/^(\d{1,2})\s+(\d{1,2})\s+(\d{4})/);
  if (spaceMatch) {
    const day = parseInt(spaceMatch[1]), month = parseInt(spaceMatch[2]), year = parseInt(spaceMatch[3]);
    if (month >= 1 && month <= 12 && day >= 1 && day <= 31)
      return year + '-' + String(month).padStart(2,'0') + '-' + String(day).padStart(2,'0');
  }
  return null;
}

function toTitleCase(str) {
  return str.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
}

function normalizePhone(phone) {
  if (!phone) return null;
  let p = String(phone).replace(/[\s\-\(\)]/g, '');
  if (p.startsWith('+65')) p = p.slice(3);
  else if (p.startsWith('65') && p.length === 10) p = p.slice(2);
  if (p.length === 8 && (p.startsWith('8') || p.startsWith('9'))) return '65' + p;
  return null;
}

// Use SGT (UTC+8) to get the correct local date regardless of server timezone
const today = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Singapore' }));
const todayMonth = today.getMonth() + 1;
const todayDay = today.getDate();

function isTodayBirthday(isoDate) {
  if (!isoDate) return false;
  const parts = isoDate.split('-');
  return parseInt(parts[1]) === todayMonth && parseInt(parts[2]) === todayDay;
}

const reminders = [];
const seenEmployers = new Set();
const seenMaids = new Set();

for (const row of allRows) {
  const employerName = String(row['Employer Name'] || '').trim();
  const maidName = String(row['Maid Name'] || '').trim();
  const phone = normalizePhone(row['Phone']);
  const employerBd = parseDate(String(row['Employer Birthday'] || '').trim());
  const maidBd = parseDate(String(row['Maid Birthday'] || '').trim());

  if (isTodayBirthday(employerBd) && employerName && phone && !seenEmployers.has(employerName.toUpperCase())) {
    seenEmployers.add(employerName.toUpperCase());
    const displayName = toTitleCase(employerName);
    const msg = encodeURIComponent('Happy Birthday ' + displayName + '! Wishing you a wonderful year ahead. Warm regards, Wiliana');
    reminders.push({
      type: 'employer',
      name: displayName,
      phone,
      waLink: 'https://wa.me/' + phone + '?text=' + msg,
    });
  }

  if (isTodayBirthday(maidBd) && maidName && employerName && phone && !seenMaids.has(maidName.toUpperCase())) {
    seenMaids.add(maidName.toUpperCase());
    const displayMaidName = toTitleCase(maidName);
    const displayEmployerName = toTitleCase(employerName);
    const msg = encodeURIComponent('Hi ' + displayEmployerName + ', a reminder that today is ' + displayMaidName + '\'s birthday! It would be a lovely gesture to wish her today. Warm regards, Wiliana');
    reminders.push({
      type: 'maid',
      name: displayMaidName,
      employerName: displayEmployerName,
      phone,
      waLink: 'https://wa.me/' + phone + '?text=' + msg,
    });
  }
}

if (reminders.length === 0) {
  return [{ json: { HAS_BIRTHDAYS: false, EMAIL_SUBJECT: '', EMAIL_BODY_HTML: '' } }];
}

const dateStr = today.toLocaleDateString('en-SG', { timeZone: 'Asia/Singapore', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

let html = '<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">';
html += '<h2 style="color: #222; border-bottom: 2px solid #eee; padding-bottom: 12px;">🎂 Birthday Reminders – ' + dateStr + '</h2>';
html += '<p style="color: #666;">You have <strong>' + reminders.length + '</strong> birthday reminder' + (reminders.length > 1 ? 's' : '') + ' today.</p>';

for (const r of reminders) {
  const isEmployer = r.type === 'employer';
  const bg = isEmployer ? '#fff8e1' : '#e8f5e9';
  const badge = isEmployer ? '👤 Employer Birthday' : '🧹 Helper Birthday';
  const title = isEmployer ? r.name : r.name;
  const sub = isEmployer ? '' : '<p style="margin: 4px 0 0 0; color: #555; font-size: 14px;">Employer: ' + r.employerName + '</p>';
  html += '<div style="background: ' + bg + '; border-radius: 10px; padding: 18px 20px; margin: 16px 0; border-left: 4px solid ' + (isEmployer ? '#f9a825' : '#43a047') + ';">';
  html += '<p style="margin: 0 0 4px 0; font-size: 11px; font-weight: bold; color: #888; text-transform: uppercase; letter-spacing: 1px;">' + badge + '</p>';
  html += '<p style="margin: 0; font-size: 20px; font-weight: bold; color: #222;">' + title + '</p>';
  html += sub;
  html += '<a href="' + r.waLink + '" style="display: inline-block; margin-top: 12px; background: #25D366; color: white; text-decoration: none; padding: 10px 22px; border-radius: 6px; font-size: 14px; font-weight: bold;">💬 Send WhatsApp →</a>';
  html += '</div>';
}

html += '</div>';

return [{ json: {
  HAS_BIRTHDAYS: true,
  EMAIL_SUBJECT: '🎂 ' + reminders.length + ' Birthday Reminder' + (reminders.length > 1 ? 's' : '') + ' – ' + dateStr,
  EMAIL_BODY_HTML: html,
} }];
